"""Generate every number table used in report.md from the results files (no hand-typed numbers).
Output: results/report_tables.md (+ results/report_numbers.json). usage: report_tables.py"""
import json, os, sys, glob
import numpy as np
sys.path.insert(0, os.path.dirname(__file__)); from core import ROOT, DATASETS
R = f"{ROOT}/results"; C = f"{R}/cells"
S = json.load(open(f"{R}/summary.json")); V = S["verdicts"]
DSN = {"agnews": "AG News", "bbc2025": "BBC 2024-25", "sst2": "SST-2", "dbpedia": "DBpedia-14", "massive": "MASSIVE-18"}
TN = {"nli": "T1 NLI", "bienc": "T2 bi-enc", "llm": "T3 LLM", "sup": "T4 sup"}
f2 = lambda x: "–" if x is None or (isinstance(x, float) and not np.isfinite(x)) else f"{x:.2f}"
f3 = lambda x: "–" if x is None or (isinstance(x, float) and not np.isfinite(x)) else f"{x:.3f}"
ci = lambda c, f=f3: f"[{f(c[0])}, {f(c[1])}]" if c else "–"
order = lambda r: (["nli", "bienc", "llm", "sup"].index(r.get("kind", "sup")), DATASETS.index(r["dataset"]), r["model"])
out = []; P = out.append
cells = {os.path.basename(f)[:-5]: json.load(open(f)) for f in glob.glob(f"{C}/*.json") if os.path.basename(f)[:-5].count("__") == 2}
P(f"# Report tables (auto-generated by src/report_tables.py from results/)\n\nZero-shot cells: {S['n_cells_zero_shot']}; supervised cells: {S['n_cells_supervised']}.\n")
# RQ1
P("## Table 1. RQ1 — variance components of mean set size, n_cal = 250, LAC, α = 0.10, design A (W valid wording sets × 200 splits)\n")
P("| type | dataset | model | mean set size | σ_wording [95% CI] | σ_split [95% CI] | ratio σ_w/σ_s [95% CI] | share_wording [95% CI] | Holm p |\n|---|---|---|---|---|---|---|---|---|")
for x in sorted(V["RQ1"]["cells"], key=order):
    c = cells[x["cell"]]; b = c["floor"][f"A|lac|valid|{x['n']}"]["set_size"]
    P(f"| {TN[x['kind']]} | {DSN[x['dataset']]} | {x['model']} | {f3(b['mean'])} | {f3(x['sd_w'])} {ci(x['ci_sd_w'])} | {f3(b['sd_s'])} {ci(b['ci_sd_s'])} | {f2(x['ratio'])} {ci(x['ci_ratio'], f2)} | {f2(x['share_w'])} {ci(x['ci_share_w'], f2)} | {x['p_holm']:.1e} |")
r1 = V["RQ1"]; P(f"\nH1a: {r1['H1a']} (share of cells with σ_w CI excluding 0 and Holm-significant F test = {f2(r1['share_cells_sd_w_ci_excludes_0_and_holm_sig'])}). "
                f"H1b: {r1['H1b']} (share of cells with ratio in [1/3, 3] = {f2(r1['share_cells_ratio_in_[1/3,3]'])}; ratio < 1/3: {f2(r1['share_cells_ratio_lt_1/3'])}; ratio > 3: {f2(r1['share_cells_ratio_gt_3'])}).")
for k in ["nli", "bienc", "llm"]:
    b = r1.get(f"by_type_{k}")
    if b: P(f"- {TN[k]}: {b['n']} cells, median ratio {f2(b['median_ratio'])}, median wording share {f2(b['median_share_w'])}, share of cells in [1/3,3] {f2(b['share_in_range'])}.")
# same for coverage
P("\n### Table 1b. Same decomposition for coverage (n = 250)\n\n| type | dataset | model | mean coverage | σ_wording [CI] | σ_split | share_wording [CI] |\n|---|---|---|---|---|---|---|")
for x in sorted(V["RQ1"]["cells"], key=order):
    b = cells[x["cell"]]["floor"][f"A|lac|valid|{x['n']}"]["coverage"]
    P(f"| {TN[x['kind']]} | {DSN[x['dataset']]} | {x['model']} | {f3(b['mean'])} | {f3(b['sd_w'])} {ci(b['ci_sd_w'])} | {f3(b['sd_s'])} | {f2(b['share_w'])} {ci(b['ci_share_w'], f2)} |")
# RQ2
P("\n## Table 2. RQ2 — floor analysis (design A, LAC, α = 0.10)\n")
P("| type | dataset | model | slope log σ_split (n ≥ 100) [CI] | slope log σ_wording (n ≥ 250) [CI] | n_max | σ_wording(n_max) [CI] | σ_split(n_max) | σ_w(W=4)/σ_w(W=30) | n* (σ_split = σ_w) |\n|---|---|---|---|---|---|---|---|---|---|")
for x in sorted(V["RQ2"]["cells"], key=order):
    P(f"| {TN[x['kind']]} | {DSN[x['dataset']]} | {x['model']} | {f2(x['slope_sd_split_n100'])} {ci(x['ci_slope_split'], f2)} | {f2(x['slope_sd_w_n250'])} {ci(x['ci_slope_w'], f2)} | {x['n_max']} | {f3(x['sd_w_nmax'])} {ci(x['ci_sd_w_nmax'])} | {f3(x['sd_s_nmax'])} | {f2(x['ratio_W4_over_Wmax'])} | {x['n_star_crossing']:.0f} |")
r2 = V["RQ2"]; P(f"\nH2a: {r2['H2a']} (share of cells with split slope in [−0.65, −0.35] = {f2(r2['share_H2a_split_slope_in_range'])}). H2b: {r2['H2b']} (share flat & CI>0 = {f2(r2['share_H2b_flat_wording_floor'])}; declining ≤ −0.35: {f2(r2['share_wording_declining'])}; CI incl. 0 at n_max: {f2(r2['share_wording_ci_includes_0_at_nmax'])}). H2c: {r2['H2c']} (share within ×[0.8,1.25] = {f2(r2['share_H2c_W4_estimate_within_0.8_1.25'])}).")
# W subsampling detail
P("\n### Table 2b. W-subsampling at n = 250: mean and 2.5–97.5 percentiles of σ_wording over 200 random W-subsets; v1-style estimator (pop. SD of W per-wording means)\n\n| type | dataset | model | W=4 mean [p2.5, p97.5] | W=8 | W=16 | W=30 | v1-style W=4 mean [p2.5, p97.5] |\n|---|---|---|---|---|---|---|---|")
for x in sorted(V["RQ1"]["cells"], key=order):
    ws = cells[x["cell"]]["w_subsample"].get(str(x["n"]))
    if not ws: continue
    Wm = str(max(int(k) for k in ws)); g = lambda w: f"{f3(ws[w]['mean_sd_w'])} [{f3(ws[w]['p2.5'])}, {f3(ws[w]['p97.5'])}]" if w in ws else "–"
    P(f"| {TN[x['kind']]} | {DSN[x['dataset']]} | {x['model']} | {g('4')} | {g('8')} | {g('16')} | {f3(ws[Wm]['mean_sd_w'])} | {f3(ws['4']['v1_popsd_mean'])} [{f3(ws['4']['v1_popsd_p2.5'])}, {f3(ws['4']['v1_popsd_p97.5'])}] |")
# design B
P("\n### Table 2c. Design B (v1 replication: fixed 300-item test set, calibration bootstrapped from the rest), LAC α = 0.10, σ of mean set size\n\n| type | dataset | model | n | σ_split | σ_wording [CI] |\n|---|---|---|---|---|---|")
for x in sorted(V["RQ1"]["cells"], key=order):
    c = cells[x["cell"]]; ns = [n for n in c["n_grid"] if f"B|lac|valid|{n}" in c["floor"]]
    for n in [ns[0], ns[-1]] if ns else []:
        b = c["floor"][f"B|lac|valid|{n}"]["set_size"]; P(f"| {TN[x['kind']]} | {DSN[x['dataset']]} | {x['model']} | {n} | {f3(b['sd_s'])} | {f3(b['sd_w'])} {ci(b['ci_sd_w'])} |")
# RQ3
r3 = V["RQ3"]
P("\n## Table 3. RQ3 — surface-only control, validity filtering\n\n| type | dataset | model | flip rate case-only (mean; max [CP 95% CI of max]) | flip rate valid sets (mean) | surface/valid | σ_w STRICT | σ_w VALID | σ_w ALL |\n|---|---|---|---|---|---|---|---|---|")
for x in sorted(r3["cells"], key=order):
    P(f"| {TN[x['kind']]} | {DSN[x['dataset']]} | {x['model']} | {f3(x['surface_flip_mean'])}; {f3(x['surface_flip_max'])} {ci(x['surface_flip_max_ci'])} | {f3(x['valid_flip_mean'])} | {f2(x['surface_over_valid'])} | {f3(x.get('sd_w_strict'))} | {f3(x.get('sd_w_valid'))} | {f3(x.get('sd_w_all'))} |")
P(f"\nH3a (case-only flips > 0 with CI excluding 0, ≥ 1 model per type): {r3['H3a_by_type']}. Share of cells with surface/valid ≥ 0.5: {f2(r3['share_cells_surface_ge_half_valid'])}. H3c: {r3['H3c']} (share σ_w VALID < ALL = {f2(r3['share_H3c_valid_lt_all'])}).")
P("\n### Table 3b. Dose-response (one class label replaced by each candidate variant; pooled within type)\n\n| type | variant×model pairs | Spearman ρ(distance, TV) [bootstrap CI] | ρ(distance, flip) | mean TV valid | mean TV invalid | H3b | ρ by dataset |\n|---|---|---|---|---|---|---|---|")
for k, d in r3["dose_response"].items():
    P(f"| {TN[k]} | {d['n_variant_model_pairs']} | {f2(d['spearman_dist_tv'])} {ci(d['ci'], f2)} | {f2(d['spearman_dist_flip'])} | {f3(d['mean_tv_valid'])} | {f3(d['mean_tv_invalid'])} | {r3['H3b'][k]} | " + ", ".join(f"{DSN[a]} {f2(b)}" for a, b in d["by_dataset"].items()) + " |")
# controls / point
P("\n## Table 4. Accuracy and controls (whole scored pool)\n\n| type | dataset | model | N | acc official | acc valid sets mean [min, max] | ECE official | share max p > 0.99 | acc nonsense (mean) | acc shuffled (mean) | identity flip | chance 1/K |\n|---|---|---|---|---|---|---|---|---|---|---|---|")
for x in sorted(S["point"], key=order):
    K = cells[x["cell"]]["K"]
    P(f"| {TN[x['kind']]} | {DSN[x['dataset']]} | {x['model']} | {x['N']} | {f3(x['acc_official'])} | {f3(x['acc_valid_mean'])} [{f3(x['acc_valid_min'])}, {f3(x['acc_valid_max'])}] | {f3(x['ece_official'])} | {f3(x['maxp_gt_099_official'])} | {f3(x['acc_nonsense'])} | {f3(x['acc_shuffled'])} | {f3(x['identity_flip'])} | {f3(1 / K)} |")
# per-set homogeneous generator sets
P("\n### Table 4b. Homogeneous-generator wording sets and the v1 hand sets (mean set size, LAC, n = 250; accuracy)\n")
for x in sorted(S["point"], key=order):
    c = cells[x["cell"]]; ps = c["per_set"]["lac"]; ks = [k for k in ps if k.startswith("homog_") or k in ("official", "identity")]
    if not ks: continue
    P(f"- {TN[x['kind']]} · {DSN[x['dataset']]} · {x['model']}: " + "; ".join(f"{k.replace('homog_', '')} size {f2(ps[k]['set_size'])} acc {f3(c['point'][k]['accuracy'])}" for k in ks))
# config shift
P("\n## Table 5. Configuration shift: calibrate with official names, deploy with each valid wording set (n = 250, LAC, α = 0.10, 200 splits)\n\n| type | dataset | model | mean coverage over sets | min | max | share of sets with mean coverage < 0.85 |\n|---|---|---|---|---|---|---|")
for x in sorted(S["point"], key=order):
    cs = [z["coverage_mean"] for z in cells[x["cell"]].get("config_shift_official_to_valid", [])]
    if cs: P(f"| {TN[x['kind']]} | {DSN[x['dataset']]} | {x['model']} | {f3(np.mean(cs))} | {f3(min(cs))} | {f3(max(cs))} | {f2(np.mean(np.array(cs) < 0.85))} |")
# methods / alpha
cc = S.get("coverage_check", {})
if cc:
    P(f"\n## Table 6. Conformal validity across methods and α (matched wording, design A)\n\nMax |mean coverage − (1 − α)| over all cells × methods × α × n: {f3(cc['max_abs_mean_coverage_minus_target'])}.\n")
    P("| type | method | α | median wording share of set-size variance (n = 250) |\n|---|---|---|---|")
    for r in S["share_w_by_method_alpha_n250"]: P(f"| {TN[r['kind']]} | {r['method'].upper()} | {r['alpha']} | {f2(r['set_size_share_w'])} |")
# RQ4
r4 = V["RQ4"]
P("\n## Table 7. RQ4 — AG News (2004-05) vs BBC (2024-10…2025-06), same 4 classes, same wording sets\n\n| type | model | acc official AG | acc official BBC | acc valid mean AG | acc valid mean BBC | σ_w AG [CI] | σ_w BBC [CI] | share max p > 0.99 AG / BBC |\n|---|---|---|---|---|---|---|---|---|")
for x in sorted(r4["pairs"], key=lambda r: (["nli", "bienc", "llm"].index(r["kind"]), r["model"])):
    P(f"| {TN[x['kind']]} | {x['model']} | {f3(x['acc_official_ag'])} | {f3(x['acc_official_bbc'])} | {f3(x['acc_valid_mean_ag'])} | {f3(x['acc_valid_mean_bbc'])} | {f3(x['sd_w_ag'])} {ci(x['ci_sd_w_ag'])} | {f3(x['sd_w_bbc'])} {ci(x['ci_sd_w_bbc'])} | {f3(x['share_maxp_gt_099_ag'])} / {f3(x['share_maxp_gt_099_bbc'])} |")
sub = sorted(k for k in cells if "_sub" in k and "_sub200" not in k)   # _sub200 = decision-model matched cells (src/mac_tables.py)
if sub:
    P("\nSubset cells (deviation; first 600 pool items, VALID strings only, NLI):\n\n| cell | N | acc official | acc valid mean | σ_w (n=250) [CI] | σ_split | share max p > 0.99 |\n|---|---|---|---|---|---|---|")
    for k in sub:
        c = cells[k]; b = c["floor"]["A|lac|valid|250"]["set_size"]; va = [c["point"][s]["accuracy"] for s in c["point"] if s.startswith("valid_")]
        P(f"| {k} | {c['N']} | {f3(c['point']['official']['accuracy'])} | {f3(np.mean(va))} | {f3(b['sd_w'])} {ci(b['ci_sd_w'])} | {f3(b['sd_s'])} | {f3(c['point']['official']['share_maxp_gt_099'])} |")
P(f"\nShare of pairs with lower valid-set accuracy on BBC: {f2(r4['H4b_acc_lower_on_bbc_share'])}; share with larger σ_w on BBC: {f2(r4['H4b_sdw_larger_on_bbc_share'])}.")
if r4["minkprob"]:
    P("\n### Table 7b. Min-K% Prob (k = 20%), first 500 pool texts per dataset, mean [bootstrap 95% CI]; higher = more 'familiar' to the LLM\n\n| LLM | " + " | ".join(DSN[d] for d in DATASETS) + " | AG − BBC |\n|---|" + "---|" * (len(DATASETS) + 1))
    for m, d in r4["minkprob"].items():
        P(f"| {m} | " + " | ".join(f"{f3(d[x]['mean'])} {ci(d[x]['ci'])}" if x in d else "–" for x in DATASETS) + f" | {f3(r4['H4a'].get(m))} |")
# supervised
P("\n## Table 8. T4 supervised reference (LogReg on frozen embeddings; BBC: trained on AG News)\n\n| dataset | model | trained on | accuracy | σ_train-bootstrap n=250 [CI] | σ_split n=250 | σ_train n_max | σ_split n_max | n_max |\n|---|---|---|---|---|---|---|---|---|")
for x in sorted(S["supervised"], key=order):
    P(f"| {DSN[x['dataset']]} | {x['model']} | {x['trained_on']} | {f3(x['acc'])} | {f3(x['sd_train_250'])} {ci(x['ci_sd_train_250'])} | {f3(x['sd_split_250'])} | {f3(x['sd_train_nmax'])} | {f3(x['sd_split_nmax'])} | {x['n_max']} |")
# sensitivity
P("\n## Table 9. Sensitivity of the wording share (n = 250) to the probability scale\n\n| cell | main share_w | sensitivity | share_w |\n|---|---|---|---|")
for k, v in sorted(cells.items()):
    for tag in ["_tau0.02", "_tau0.1", "_rawll"]:
        if k.endswith(tag) and k[: -len(tag)] in cells:
            b = cells[k[: -len(tag)]]; n = 250 if 250 in b["n_grid"] else b["n_grid"][0]
            P(f"| {k[: -len(tag)]} | {f2(b['floor'][f'A|lac|valid|{n}']['set_size']['share_w'])} | {tag[1:]} | {f2(v['floor'][f'A|lac|valid|{n}']['set_size']['share_w'])} |")
# repeatability
p = f"{R}/repeatability.json"
if os.path.exists(p):
    RP = json.load(open(p)); P("\n## Table 10. RQ5 — repeatability (identical fresh-process runs) and intermediate-precision conditions (AG News)\n")
    P("| type | condition | wording | max abs Δp | argmax flips | share of conformal test sets changed | ICC(2,1) | Fleiss κ |\n|---|---|---|---|---|---|---|---|")
    for inst, r in RP.items():
        if inst.startswith("api-"): continue  # API test-retest: results/api/api_tables.md Table A6
        for w, v in r.items():
            if isinstance(v, dict) and "max_abs_dp" in v: P(f"| {TN[inst]} | {r['runs']} identical runs | {w} | {v['max_abs_dp']:.2e} | – | {f3(v['share_test_sets_changed'])} | {f3(v['icc21'])} | {f3(v['fleiss_kappa'])} |")
        for c, row in r["conditions_vs_rep0"].items():
            for w in ["official", "v1_w1"]:
                if w in row: v = row[w]; P(f"| {TN[inst]} | {c} vs rep0 | {w} | {v['max_abs_dp']:.2e} | {f3(v['argmax_flips'])} | {f3(v['share_test_sets_changed'])} | – | – |")
# template factor
p = f"{R}/template_factor.json"
if os.path.exists(p):
    TF = json.load(open(p)); P("\n## Table 11. Exploratory template factor (T2 bi-encoders; 3 templates × W valid sets × 200 splits; n = 250, LAC)\n\n| cell | acc official tpl0/tpl1/tpl2 | σ_template | σ_wording | σ_split | σ_template×wording | σ_w within tpl0 / tpl1 / tpl2 |\n|---|---|---|---|---|---|---|")
    for k, r in sorted(TF.items()):
        a = r["acc_official"]; s3 = r["sd3"]; w = r["sd_w_within_template"]
        P(f"| {k} | {f3(a['tpl0'])} / {f3(a['tpl1'])} / {f3(a['tpl2'])} | {f3(s3['t'])} | {f3(s3['w'])} | {f3(s3['s'])} | {f3(s3['tw'])} | {f3(w['tpl0']['sd_w'])} / {f3(w['tpl1']['sd_w'])} / {f3(w['tpl2']['sd_w'])} |")
# v1 reanalysis
p = f"{R}/v1_reanalysis.json"
if os.path.exists(p):
    V1 = json.load(open(p)); P("\n## Table 12. Re-analysis of published v1 numbers (committed v1 outputs)\n\n| instrument | published u_wording (pop. SD, W=4) | SD ddof=1 [χ² 95% CI] | published-style share [bootstrap CI] | v2-method share_w [CI] | v2-method ratio σ_w/σ_s [CI] | coverage share_w [CI] |\n|---|---|---|---|---|---|---|")
    for m in ["clef", "qwen3.5"]:
        r = V1[m]; v = r["v2_method_set_size"]; cv = r["v2_method_coverage"]
        P(f"| {m} | {f3(r['u_wording_published_popsd'])} | {f3(r['sd_wording_ddof1'])} {ci(r['chi2_95ci_sd_wording_ddof1'])} | {f2(r['published_style_share_wording_vs_cal_only'])} {ci(r['published_style_share_bootstrap_95ci'], f2)} | {f2(v['share_w'])} {ci(v['ci_share_w'], f2)} | {f2(v['ratio_w_s'])} {ci(v['ci_ratio_w_s'], f2)} | {f2(cv['share_w'])} {ci(cv['ci_share_w'], f2)} |")
    b = V1["clef_share_by_n_fixed_test"]; P("\nClef share of wording by n (v1 500-item pool, fixed test): " + "; ".join(f"n={n}: share {f2(x['share_w'])} {ci(x['ci_share_w'], f2)}, σ_w {f3(x['sd_w'])}, σ_s {f3(x['sd_s'])}" for n, x in b.items()))
open(f"{R}/report_tables.md", "w").write("\n".join(out) + "\n"); print("wrote", f"{R}/report_tables.md", len(out), "lines")
